import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788284319000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>WOODPECKER_URL</code></td><td>yes</td><td>—</td><td>Server root, e.g. <code>https://woodpecker.example.com</code>. A trailing <code>/api</code> is trimmed</td></tr><tr><td><code>WOODPECKER_TOKEN</code></td><td>yes</td><td>—</td><td>Personal access token from User settings → CLI and API</td></tr><tr><td><code>WOODPECKER_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the 34 read tools</td></tr><tr><td><code>WOODPECKER_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>WOODPECKER_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>WOODPECKER_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates, scoped to this connection</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>Booleans are the exact string <code>true</code>; anything else, including <code>1</code> and <code>TRUE</code>, is false. That is deliberate — a variable that means &quot;on&quot; for four spellings and &quot;off&quot; for a fifth is worse than one with a single spelling.</p><h2 id="woodpecker-url" tabindex="-1"><code>WOODPECKER_URL</code> <a class="header-anchor" href="#woodpecker-url" aria-label="Permalink to “WOODPECKER_URL”">​</a></h2><p>The URL you open in a browser. Not <code>.../api</code>, though that suffix is trimmed rather than refused, because the Swagger page spells every example the long way.</p><p>Refused outright, with an exit rather than a warning:</p><ul><li>a URL that is not <code>http:</code> or <code>https:</code></li><li>a URL containing credentials (<code>https://user:pass@host</code>) — those end up in logs</li><li>a URL that does not parse</li></ul><p>The value is never echoed back in the error. A token pasted into the wrong variable is a mistake people make, and printing it into the client&#39;s log would be the second one.</p><p>Plain <code>http:</code> to a non-local host is allowed but warns: the token then travels unencrypted.</p><h2 id="woodpecker-token" tabindex="-1"><code>WOODPECKER_TOKEN</code> <a class="header-anchor" href="#woodpecker-token" aria-label="Permalink to “WOODPECKER_TOKEN”">​</a></h2><p>Read once at start-up and then deleted from <code>process.env</code>, so a child process or a crash report cannot pick it up.</p><p>Woodpecker has no token scopes — the token carries the full authority of its account. <code>get_current_user</code> reports which account that is.</p><p>Without it the server still starts and lists its tools, so registries and sandbox inspectors can introspect it. Every call except <code>get_server_info</code> then fails with setup instructions instead of reaching the API.</p><h2 id="woodpecker-allow-tools-and-woodpecker-deny-tools" tabindex="-1"><code>WOODPECKER_ALLOW_TOOLS</code> and <code>WOODPECKER_DENY_TOOLS</code> <a class="header-anchor" href="#woodpecker-allow-tools-and-woodpecker-deny-tools" aria-label="Permalink to “WOODPECKER_ALLOW_TOOLS and WOODPECKER_DENY_TOOLS”">​</a></h2><p>Comma-separated tool names, a prefix with one trailing <code>*</code>, or <code>essential</code>. Allow decides what is in; deny is subtracted from it. An entry matching no tool aborts start-up rather than being ignored.</p><p>See <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a> for what that buys and how it fails.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where <code>WOODPECKER_READ_ONLY</code> fails <em>off</em> on a typo, this one stops the server with exit code 1 — through the same <code>fail()</code> every other refusal in <code>config.ts</code> uses. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>WOODPECKER_TOKEN</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the token sitting there for a crash reporter.</p><h2 id="woodpecker-insecure-tls" tabindex="-1"><code>WOODPECKER_INSECURE_TLS</code> <a class="header-anchor" href="#woodpecker-insecure-tls" aria-label="Permalink to “WOODPECKER_INSECURE_TLS”">​</a></h2><p>Accepts a self-signed certificate for this server&#39;s connection only, through a dedicated undici dispatcher. <code>NODE_TLS_REJECT_UNAUTHORIZED</code> is never set, so nothing else in the process loses certificate validation.</p><p>Prefer an internal CA your machine trusts.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};